12534: # POSTs with the intake's rate rule: a 429 whose Retry-After is at most 60 s - and (wave 28b, D2)
12535: # fits into $BudgetMs, what is left of the flush's deadline (0: no deadline) - is waited for and the
12536: # SAME request sent once more; a longer or missing Retry-After, or a second 429, stops there. No
12537: # other retry. Every request is bounded by $TotalMs (and by the budget).
12538: function Invoke-TelemetrySend {
12539:     param([string]$Url, [string]$Body, [int]$ConnectMs = 3000, [int]$TotalMs = 8000, [long]$BudgetMs = 0)
12540:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
12541:     $one = { param([long]$Left) if ($BudgetMs -gt 0) { [int][Math]::Max(100, [Math]::Min([long]$TotalMs, $Left)) } else { $TotalMs } }
12542:     $r = Invoke-TelemetryPost -Url $Url -Body $Body -ConnectMs $ConnectMs -TotalMs (& $one ($BudgetMs - $watch.ElapsedMilliseconds))
12543:     if ($r.Status -eq 429) {
12544:         $left = $BudgetMs - $watch.ElapsedMilliseconds
12545:         if ($r.RetryAfter -ge 0 -and $r.RetryAfter -le $script:TelemetryRetryAfterMax -and ($BudgetMs -le 0 -or ([long]$r.RetryAfter * 1000 + 1000) -lt $left)) {
12546:             Start-Sleep -Seconds $r.RetryAfter
12547:             $r = Invoke-TelemetryPost -Url $Url -Body $Body -ConnectMs $ConnectMs -TotalMs (& $one ($BudgetMs - $watch.ElapsedMilliseconds))
12548:             if ($r.Status -eq 429) { $r.Why = 'HTTP 429 again after its Retry-After' }
12549:         } elseif ($r.RetryAfter -ge 0 -and $r.RetryAfter -le $script:TelemetryRetryAfterMax) {
12550:             $r.Why = "HTTP 429 (Retry-After $($r.RetryAfter) s does not fit into the flush's deadline: not retried now)"
12551:         } else {
12552:             $r.Why = "HTTP 429 (Retry-After $(if ($r.RetryAfter -ge 0) { "$($r.RetryAfter) s, more than $($script:TelemetryRetryAfterMax) s" } else { 'not given' }): not retried now)"
12553:         }
12554:     }
12555:     return $r
12556: }
