12558: # Removes $Lines (a multiset of exact lines) from a spool file - lines appended before stay; an
12559: # emptied file is deleted. (wave 28d, D1 / F48-1, F49-3) The rewrite is ATOMIC: under the telemetry
12560: # lock (Enter-TelemetryLock -IgnoreMarker - no producer appends meanwhile) the file is read under its
12561: # exclusive handle, the kept lines go to <spool file>.tmp in the same directory (a .tmp a crash left
12562: # behind is replaced), are flushed to disk, and the temporary file REPLACES the spool file in one step
12563: # ([IO.File]::Move with overwrite; MoveFileEx(REPLACE_EXISTING | WRITE_THROUGH) on Windows PowerShell
12564: # 5.1, as Write-TextAtomic) - nothing truncates the spool in place: a crash leaves the old file or the
12565: # new one, never a truncated one. A replace that keeps failing leaves the spool as it was (its
12566: # delivered lines are sent again later - at least once). $WaitMs (wave 28c, D5: what is left of the
12567: # flush's deadline) bounds the waits for the lock and the file BEFORE the rewrite starts; nothing
12568: # inside the rewrite is cut by the deadline. TEST HOOK (test mode only):
12569: # CODEX_CONSULT_TEST_TELEMETRY_REWRITE_CRASH=1 - the process exits (code 86) between the temporary
12570: # file and the replace, as a crash would. '' when done, else why not.
12571: function Remove-TelemetrySpoolLines {
12572:     param([string]$Path, [string[]]$Lines, [int]$WaitMs = 2000)
12573:     if (@($Lines).Count -eq 0) { return '' }
12574:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
12575:     $lk = Enter-TelemetryLock -WaitMs $WaitMs -IgnoreMarker
12576:     if (-not $lk.Ok) { return "the spool file '$Path' was not rewritten ($($lk.Why))" }
12577:     try {
12578:         $fs = Open-TelemetrySpoolFile -Path $Path -WaitMs ([int][Math]::Max(50, $WaitMs - $watch.ElapsedMilliseconds))
12579:         if (-not $fs) { return "the spool file '$Path' stayed busy" }
12580:         $keep = New-Object System.Collections.Generic.List[string]
12581:         try {
12582:             $remove = New-Object 'System.Collections.Generic.Dictionary[string,int]'
12583:             foreach ($l in $Lines) { if ($remove.ContainsKey($l)) { $remove[$l]++ } else { $remove[$l] = 1 } }
12584:             foreach ($l in (Read-TelemetryStreamLines $fs)) {
12585:                 if ($remove.ContainsKey($l) -and $remove[$l] -gt 0) { $remove[$l]--; continue }
12586:                 $keep.Add($l)
12587:             }
12588:         } finally { $fs.Dispose() }
12589:         $tmp = "$Path.tmp"
12590:         if ($keep.Count -eq 0) {
12591:             [IO.File]::Delete($Path)
12592:             try { if ([IO.File]::Exists($tmp)) { [IO.File]::Delete($tmp) } } catch { }
12593:             return ''
12594:         }
12595:         $bytes = $script:Utf8NoBom.GetBytes(($keep.ToArray() -join "`n") + "`n")
12596:         $ts = New-Object System.IO.FileStream($tmp, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
12597:         try { $ts.Write($bytes, 0, $bytes.Length); $ts.Flush($true) } finally { $ts.Dispose() }
12598:         if ((Get-TestHookValue 'CODEX_CONSULT_TEST_TELEMETRY_REWRITE_CRASH').Trim() -eq '1') { [Environment]::Exit(86) }
12599:         $lastError = $null
12600:         for ($attempt = 1; $attempt -le 8; $attempt++) {
12601:             try {
12602:                 if (-not $script:LegacyPS) {
12603:                     [IO.File]::Move($tmp, $Path, $true)
12604:                 } elseif (Test-NativeMove) {
12605:                     if (-not [CodexConsultNative]::MoveFileEx($tmp, $Path, 0x9)) { throw (New-Object System.ComponentModel.Win32Exception([Runtime.InteropServices.Marshal]::GetLastWin32Error())) }
12606:                 } else {
12607:                     [IO.File]::Replace($tmp, $Path, [System.Management.Automation.Language.NullString]::Value)
12608:                 }
12609:                 return ''
12610:             } catch {
12611:                 # a reader holding the spool file open without FileShare.Delete: gone a moment later
12612:                 $lastError = $_.Exception
12613:                 Start-Sleep -Milliseconds 250
12614:             }
12615:         }
12616:         try { [IO.File]::Delete($tmp) } catch { }
12617:         return "the spool file '$Path' could not be replaced ($(ConvertTo-OneLine $lastError.Message)); it is kept as it was"
12618:     } catch { return (ConvertTo-OneLine $_.Exception.Message) } finally { Exit-TelemetryLock }
12619: }
