12621: # The spool as it is: { Files; Events; Complaints; Invalid; Oldest (unix s or $null) } - read-only.
12622: function Get-TelemetrySpoolCounts {
12623:     $c = [pscustomobject]@{ Files = 0; Events = 0; Complaints = 0; Invalid = 0; Oldest = $null }
12624:     $p = Get-TelemetryPaths
12625:     if (-not $p -or -not [IO.Directory]::Exists($p.Spool)) { return $c }
12626:     foreach ($f in @(Get-ChildItem -LiteralPath $p.Spool -File -Filter '*.ndjson' | Sort-Object Name)) {
12627:         $c.Files++
12628:         foreach ($l in @((Read-SharedText -Path $f.FullName) -split "`n" | ForEach-Object { $_.TrimEnd("`r") } | Where-Object { $_ })) {
12629:             $s = ConvertFrom-TelemetrySpoolLine $l
12630:             if (-not $s) { $c.Invalid++; continue }
12631:             if ($s.Kind -eq 'event') { $c.Events++ } else { $c.Complaints++ }
12632:             if ($null -eq $c.Oldest -or $s.Queued -lt $c.Oldest) { $c.Oldest = $s.Queued }
12633:         }
12634:     }
12635:     return $c
12636: }
