12716: # (wave 28d, D3) A flush lock's owner as its text says: { Pid; Since; Owner - 'alive' (its pid and
12717: # start time live, or its identity cannot be confirmed: Test-PidAlive), 'gone', 'none' (the lock names
12718: # no owner or cannot be read) }. Read only.
12719: function Get-TelemetryFlushLockOwner {
12720:     param([string]$Text)
12721:     $o = [pscustomobject]@{ Pid = 0; Since = ''; Owner = 'none' }
12722:     $rec = $null
12723:     try { if (([string]$Text).Trim().StartsWith('{')) { $rec = ConvertFrom-JsonKeepOffset -Text $Text } } catch { $rec = $null }
12724:     $n = Get-TelemetryCount (Get-PropertyValue $rec 'pid' $null)
12725:     if ($null -ne $n -and $n -le [int]::MaxValue) { $o.Pid = [int]$n }
12726:     $o.Since = [string](ConvertTo-JsonText (Get-PropertyValue $rec 'since' ''))
12727:     if ($o.Pid -gt 0) { $o.Owner = $(if (Test-PidAlive -ProcessId $o.Pid -StartTime ([string](ConvertTo-StartIso (Get-PropertyValue $rec 'start_time' '')))) { 'alive' } else { 'gone' }) }
12728:     return $o
12729: }
