12731: # (wave 28c, D4) Whether the sender's lock still carries $Token: read without taking it (shared); a
12732: # lock that is gone, names another token or cannot be read within about 1 s is NOT this sender's -
12733: # the sender then stops without rewriting the spool or sending more.
12734: function Test-TelemetryFlushLockMine {
12735:     param([string]$Path, [string]$Token)
12736:     for ($i = 0; $i -lt 20; $i++) {
12737:         try {
12738:             if (-not [IO.File]::Exists($Path)) { return $false }
12739:             $fs = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
12740:             try {
12741:                 $sr = New-Object System.IO.StreamReader($fs, $script:Utf8NoBom, $false, 4096, $true)
12742:                 try { $text = $sr.ReadToEnd() } finally { $sr.Dispose() }
12743:             } finally { $fs.Dispose() }
12744:             try { return (([string](Get-PropertyValue (ConvertFrom-Json -InputObject $text) 'token' '')) -ceq $Token) } catch { return $false }
12745:         } catch { Start-Sleep -Milliseconds 50 }
12746:     }
12747:     return $false
12748: }
