12750: # Releases the sender's lock when it still carries $Token (a lock taken over by another sender stays).
12751: function Exit-TelemetryFlushLock {
12752:     param([string]$Path, [string]$Token)
12753:     for ($i = 0; $i -lt 20; $i++) {
12754:         try {
12755:             if (-not [IO.File]::Exists($Path)) { return }
12756:             $mine = $false
12757:             $fs = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None)
12758:             try {
12759:                 $sr = New-Object System.IO.StreamReader($fs, $script:Utf8NoBom, $false, 4096, $true)
12760:                 try { $text = $sr.ReadToEnd() } finally { $sr.Dispose() }
12761:                 try { $mine = ([string](Get-PropertyValue (ConvertFrom-Json -InputObject $text) 'token' '')) -ceq $Token } catch { $mine = $false }
12762:             } finally { $fs.Dispose() }
12763:             if ($mine) { [IO.File]::Delete($Path) }
12764:             return
12765:         } catch { Start-Sleep -Milliseconds 50 }
12766:     }
12767: }
