129: # Process start time as a UTC round-trip string. $null: no such process. '': the
130: # process exists but its start time cannot be read (e.g. another user's process).
131: # (wave 28c, D8) TEST HOOK (test mode only): CODEX_CONSULT_TEST_START_UNREADABLE=<pid>[,<pid>] - these
132: # pids, while they exist, read as '' (a start time that cannot be read).
133: function Get-ProcessStartIso {
134:     param([int]$ProcessId)
135:     $p = $null
136:     try { $p = Get-Process -Id $ProcessId -ErrorAction Stop } catch { return $null }
137:     $unreadable = [string][Environment]::GetEnvironmentVariable('CODEX_CONSULT_TEST_START_UNREADABLE')
138:     if ($unreadable -and ([string][Environment]::GetEnvironmentVariable('CODEX_CONSULT_TEST_MODE')).Trim() -eq '1') {
139:         if (@($unreadable.Split(',') | ForEach-Object { $_.Trim() }) -contains [string]$ProcessId) { return '' }
140:     }
141:     try { return $p.StartTime.ToUniversalTime().ToString('o', $script:Invariant) } catch { return '' }
142: }
143: 
144: # Do two start times (UTC round-trip strings from Get-ProcessStartIso) name the same
145: # process start? Windows reports a process's start time exactly. .NET on Linux derives
146: # Process.StartTime from a boot time that every process computes for itself
147: # (CLOCK_REALTIME_COARSE - CLOCK_BOOTTIME), so two processes reading the SAME pid get
148: # values a few milliseconds apart. Outside Windows, less than one second apart counts
149: # as the same start (a pid is not handed out again that fast).
150: function Test-SameStartTime {
151:     param([string]$A, [string]$B)
152:     if ($A -eq $B) { return $true }
153:     if ($script:OnWindows) { return $false }
154:     $ta = [DateTimeOffset]::MinValue
155:     $tb = [DateTimeOffset]::MinValue
156:     $styles = [System.Globalization.DateTimeStyles]::AssumeUniversal
157:     if (-not [DateTimeOffset]::TryParse($A, $script:Invariant, $styles, [ref]$ta)) { return $false }
158:     if (-not [DateTimeOffset]::TryParse($B, $script:Invariant, $styles, [ref]$tb)) { return $false }
159:     return ([math]::Abs($ta.UtcTicks - $tb.UtcTicks) -lt [TimeSpan]::TicksPerSecond)
160: }
161: 
162: # (wave 28c, D8 / F42-4) The identity of a pid against the start time read for it before: 'alive' (a
163: # process with this pid exists AND has that start time), 'gone' (no such process, or one with another
164: # start time - the pid was handed to another process), 'unknown' (a process with this pid exists, but
165: # the start time recorded or the one read now is unreadable - its identity cannot be confirmed). A
166: # KILL acts on 'alive' only and never counts 'unknown' as gone (Stop-ProcessTreeChecked); a holder of
167: # a lock or a record counts as alive on 'unknown' (Test-PidAlive: never taken over on a guess).
168: function Get-PidIdentity {
169:     param([int]$ProcessId, [string]$StartTime = '')
170:     if ($ProcessId -le 0) { return 'gone' }
171:     $live = Get-ProcessStartIso -ProcessId $ProcessId
172:     if ($null -eq $live) { return 'gone' }
173:     if (-not $StartTime -or -not $live) { return 'unknown' }
174:     if (Test-SameStartTime -A $live -B $StartTime) { return 'alive' }
175:     return 'gone'
176: }
177: 
178: # A pid counts as alive when a process with that id exists and - if a start time was
179: # recorded for it - still has that start time (otherwise the pid was reused). (wave 28c, D8) An
180: # identity that cannot be confirmed ('unknown' of Get-PidIdentity) counts as ALIVE here: a holder is
181: # never taken over, a survivor never released, on a guess.
182: function Test-PidAlive {
183:     param([int]$ProcessId, [string]$StartTime = '')
184:     if ($ProcessId -le 0) { return $false }
185:     $live = Get-ProcessStartIso -ProcessId $ProcessId
186:     if ($null -eq $live) { return $false }
187:     if ($StartTime -and $live -and -not (Test-SameStartTime -A $live -B $StartTime)) { return $false }
188:     return $true
189: }
190: 
191: # (wave 28e, E3 / F54-3) A process's start time as a whole number of ticks (UTC, 100 ns - the full
192: # resolution Windows reports; read through Get-ProcessStartIso, so its test hook applies): $null - no
193: # such process; -1 - the process exists but its start time cannot be read; else the ticks.
194: function Get-ProcessStartTicks {
195:     param([int]$ProcessId)
196:     if ($ProcessId -le 0) { return $null }
197:     $iso = Get-ProcessStartIso -ProcessId $ProcessId
198:     if ($null -eq $iso) { return $null }
199:     $t = [DateTimeOffset]::MinValue
200:     if ($iso -and [DateTimeOffset]::TryParse($iso, $script:Invariant, [System.Globalization.DateTimeStyles]::AssumeUniversal, [ref]$t)) { return [long]$t.UtcTicks }
201:     return [long]-1
202: }
203: 
204: # (wave 28e, E3, E2) The identity of a pid against the start ticks recorded for it (Get-ProcessStartTicks):
205: # 'alive' (a process with this pid runs with EXACTLY those ticks - outside Windows within the same
206: # second, the jitter Test-SameStartTime explains), 'gone' (no such process, or one with another start:
207: # the pid was handed to another process), 'unknown' (no ticks were recorded, or the start time cannot
208: # be read now). A holder counts as alive on 'unknown' - never removed on a guess.
209: function Get-PidIdentityTicks {
210:     param([int]$ProcessId, [long]$StartTicks = 0)
211:     if ($ProcessId -le 0) { return 'gone' }
212:     $live = Get-ProcessStartTicks -ProcessId $ProcessId
213:     if ($null -eq $live) { return 'gone' }
214:     if ($StartTicks -le 0 -or $live -lt 0) { return 'unknown' }
215:     if ($live -eq $StartTicks) { return 'alive' }
216:     if (-not $script:OnWindows -and [math]::Abs($live - $StartTicks) -lt [TimeSpan]::TicksPerSecond) { return 'alive' }
217:     return 'gone'
218: }
