   250:     try { $lAge = [int]([DateTime]::UtcNow - [IO.File]::GetLastWriteTimeUtc($p.Lock)).TotalSeconds } catch { }
   251:     $lSince = $(if ($lo.Since) { $lo.Since } else { try { [IO.File]::GetLastWriteTimeUtc($p.Lock).ToLocalTime().ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant) } catch { '?' } })
   252:     if ($lo.Owner -eq 'alive' -and $lAge -ge $script:TelemetryStuckLockSec) { Write-Host "sender     : sender stuck since $lSince (pid $($lo.Pid)) - its lock $($p.Lock) is $([int]($lAge / 60)) min old and its owner lives: it is never taken over; stop pid $($lo.Pid) if it hangs, or delete the lock when no such process runs" -ForegroundColor Yellow }
   253:     elseif ($lo.Owner -eq 'alive') { Write-Host "sender     : busy since $lSince (pid $($lo.Pid) holds its lock, $lAge s old)" }
   254:     elseif ($lo.Owner -eq 'gone') { Write-Host "sender     : a lock whose owner pid $($lo.Pid) is gone - the next sender removes it" }
   255:     else { Write-Host "sender     : a lock that names no owner ($lAge s old) - held while younger than $($script:TelemetryOwnerlessLockSec) s, then removed by the next sender" }
   256: }
   257: $last = Read-TelemetryLast
   258: $lastResult = [string](Get-PropertyValue $last 'result' '')
   259: Write-Host "last flush : $(if ($lastResult) { "$([string](ConvertTo-JsonText (Get-PropertyValue $last 'time' ''))) - $lastResult" } else { 'never' })"
   260: # (wave 28d, D2, D3) what the telemetry client did or saw on its own (.last notes)
   261: foreach ($nt in @(Get-PropertyValue $last 'notes' @())) { if ($nt) { Write-Host "note       : $nt" } }
   262: $iid = Get-TelemetryInstanceId
   263: Write-Host "instance id: $(if ($iid) { "$iid (SHA-256 of the salt $($p.Salt) and the machine name; a new salt makes a new instance)" } else { '(none yet - the first event creates the salt)' })"
   264: Write-Host "notice     : $(if ([IO.File]::Exists($p.Notice)) { "shown for $(Get-BridgeVersion) ($($p.Notice))" } else { "not shown yet for $(Get-BridgeVersion) - the next consultation with telemetry on prints it" })"
   265: exit 0
